Method.Source:
/// <summary>
/// Finds record for Alliance markup
/// </summary>
/// <param name = "accountRelation">custvend account</param>
/// <param name = "itemCode">item code</param>
/// <param name = "itemRelation">item</param>
/// <param name = "markupReturn">markup return type</param>
/// <param name = "returnRelation">return code</param>
/// <param name = "_forUpdate">true or false</param>
/// <param name = "_moduleCategory">MarkupModuleCategory</param>
/// <returns>record</returns>
[SuppressBPWarning('BPParameterNotUsed', 'False positive')]
public static MarkupAutoTable KCS_findAllianceMarkup(CustVendRel            accountRelation,
                                                 TableGroupAll          itemCode,
                                                 ItemRelation           itemRelation,
                                                 MarkupReturnType       markupReturn = ReturnCodeType::None,
                                                 ReturnCode             returnRelation = '',
                                                  boolean               _forUpdate = false,
                                                 MarkupModuleCategory  _moduleCategory = HeadingLine::Heading)

{
    CustTable           custTable;
    AccountNum          allianceId;
    MarkupAutoTable     markupAutoTable;
    ;

    if (accountRelation)
    {
        allianceId = accountRelation;

        select firstonly AccountNum, KCS_BOSAllianceID, recId from custTable 
            where custTable.AccountNum == allianceId;

        while (custTable.RecId)
        {
            /*markupAutoTable = MarkupAutoTable::find(_moduleCategory,
                                                MarkupModuleType::Cust,
                                                TableGroupAll::GroupId,
                                                custTable.AccountNum,
                                                itemCode,
                                                itemRelation,
                                                ReturnCodeType::None,
                                                '');*/
            MarkupAutoTable searchParameter;

            searchParameter.ModuleCategory    = _moduleCategory;
            searchParameter.ModuleType        = MarkupModuleType::Cust;
            searchParameter.AccountCode       = TableGroupAll::GroupId;
            searchParameter.AccountRelation   = custTable.AccountNum;
            searchParameter.ItemCode          = itemCode;
            searchParameter.ItemRelation      = itemRelation;

            searchParameter.MarkupReturn      = ReturnCodeType::None;
            searchParameter.ReturnRelation    = '';
            searchParameter.DlvModeCode       = TableGroupAll::All;
            searchParameter.DlvModeRelation   = '';


            markupAutoTable = MarkupAutoTable::findByNaturalKey(searchParameter);

            if (markupAutoTable)
            {
                break;
            }
            else
            {
                allianceId = custTable.KCS_BOSAllianceID;
                if (allianceId)
                {
                    select firstonly AccountNum,KCS_BOSAllianceID,RecId from custTable
                        where custTable.AccountNum == allianceId
                        && custTable.KCS_BOSAllianceID != allianceId;
                }
                else
                {
                    break;
                }
            }
        }
    }
    return markupAutoTable;
}
